{
  "items": [
    {
      "name": "MvPowerSeries.weightedOrder_mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] [NoZeroDivisors R] (w : σ → ℕ) (f g : MvPowerSeries σ R),\n  MvPowerSeries.weightedOrder w (f * g) = MvPowerSeries.weightedOrder w f + MvPowerSeries.weightedOrder w g"
    },
    {
      "name": "Polynomial.rootMultiplicity_mul",
      "module_name": "Mathlib.Algebra.Polynomial.RingDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] [IsDomain R] {p q : Polynomial R} {x : R},\n  p * q ≠ 0 → Polynomial.rootMultiplicity x (p * q) = Polynomial.rootMultiplicity x p + Polynomial.rootMultiplicity x q"
    },
    {
      "name": "MvPowerSeries.weightedOrder_prod",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.NoZeroDivisors",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_3} [inst : CommSemiring R] [NoZeroDivisors R] [Nontrivial R] {ι : Type u_4} (w : σ → ℕ)\n  (f : ι → MvPowerSeries σ R) (s : Finset ι),\n  MvPowerSeries.weightedOrder w (∏ i ∈ s, f i) = ∑ i ∈ s, MvPowerSeries.weightedOrder w (f i)"
    },
    {
      "name": "Polynomial.rootMultiplicity_mul'",
      "module_name": "Mathlib.Algebra.Polynomial.RingDivision",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommRing R] {p q : Polynomial R} {x : R},\n  Polynomial.eval x (p /ₘ (Polynomial.X - Polynomial.C x) ^ Polynomial.rootMultiplicity x p) *\n        Polynomial.eval x (q /ₘ (Polynomial.X - Polynomial.C x) ^ Polynomial.rootMultiplicity x q) ≠\n      0 →\n    Polynomial.rootMultiplicity x (p * q) = Polynomial.rootMultiplicity x p + Polynomial.rootMultiplicity x q"
    },
    {
      "name": "Polynomial.degree_mul",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Operations",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] [NoZeroDivisors R] {p q : Polynomial R}, (p * q).degree = p.degree + q.degree"
    }
  ]
}
